package ru.threediwell.fm.farm;

import org.json.*;
import org.junit.Test;
import java.util.*;
import java.util.stream.Collectors;
import ru.threediwell.fm.i18n.I18n;
import static org.junit.Assert.*;

public class FarmSortTest {
    private JSONObject printer(String id,String name,String model)throws Exception{return new JSONObject().put("id",id).put("name",name).put("model",model);}
    private JSONObject file(String name)throws Exception{return new JSONObject().put("filename",name).put("file_id",name).put("is_printable",1);}
    private JSONObject part(String id,int printed,int required)throws Exception{return new JSONObject().put("part_id",id).put("printed_qty",printed).put("required_qty",required);}
    private JSONObject state(String status)throws Exception{return new JSONObject().put("status",status).put("seen_ago",0);}
    private String names(List<JSONObject> rows,String key){return rows.stream().map(r->r.optString(key)).collect(Collectors.joining(","));}
    @Test public void printerNamesUseNaturalNumbers()throws Exception {JSONArray a=new JSONArray().put(printer("10","P10","X1")).put(printer("2","P2","X1")).put(printer("1","P1","X1"));assertEquals("P1,P2,P10",names(FarmSort.printers(a,new JSONObject(),1,"name",false),"name"));}
    @Test public void namesDescendingIsExplicit()throws Exception {JSONArray a=new JSONArray().put(file("plate2.gcode")).put(file("plate10.gcode"));assertEquals("plate10.gcode,plate2.gcode",names(FarmSort.files(a,"name",true),"filename"));}
    @Test public void printerModelsThenNamesAreStable()throws Exception {JSONArray a=new JSONArray().put(printer("b","B","X10")).put(printer("c","C","X2")).put(printer("a","A","X2"));assertEquals("a,c,b",names(FarmSort.printers(a,new JSONObject(),1,"model",false),"id"));assertEquals("b,a,c",names(FarmSort.printers(a,new JSONObject(),1,"model",true),"id"));}
    @Test public void duplicateNamesHaveStableIdentifierTieBreak()throws Exception {JSONArray a=new JSONArray().put(printer("b","P1","X1")).put(printer("a","P1","X1"));assertEquals("a,b",names(FarmSort.printers(a,new JSONObject(),1,"name",false),"id"));}
    @Test public void statusPrioritizesOperatorAttentionAndFinishedPrints()throws Exception {String[] statuses={"OFFLINE","IDLE","SLICING","RUNNING","FINISH","PAUSED","FAILED"};JSONArray rows=new JSONArray();JSONObject states=new JSONObject();for(String s:statuses){rows.put(printer(s,s,"X1"));states.put(s,state(s));}assertEquals("FAILED,PAUSED,FINISH,RUNNING,SLICING,IDLE,OFFLINE",names(FarmSort.printers(rows,states,1,"status",false),"id"));}
    @Test public void statusReverseAlsoIncludesEveryPrinter()throws Exception {JSONArray a=new JSONArray().put(printer("a","A","X1")).put(printer("b","B","X1"));JSONObject states=new JSONObject().put("a",state("ERROR")).put("b",state("IDLE"));assertEquals("b,a",names(FarmSort.printers(a,states,1,"status",true),"id"));}
    @Test public void expiredSnapshotIsNotAnIdlePrinter()throws Exception {assertEquals(8,FarmSort.printerRank(state("IDLE"),6500));assertEquals(8,FarmSort.printerRank(state("RUNNING").put("seen_ago",60),1));assertEquals(8,FarmSort.printerRank(null,1));}
    @Test public void absentFreshnessRanksDisconnected()throws Exception {assertEquals(8,FarmSort.printerRank(new JSONObject().put("status","IDLE"),1));}
    @Test public void pauseAndFailureAliasesHaveSameRanks()throws Exception {assertEquals(FarmSort.printerRank(state("PAUSE"),1),FarmSort.printerRank(state("PAUSED"),1));assertEquals(FarmSort.printerRank(state("ERROR"),1),FarmSort.printerRank(state("FAILED"),1));}
    @Test public void unknownStatusCannotLookReady()throws Exception {assertTrue(FarmSort.printerRank(state("UNKNOWN"),1)>FarmSort.printerRank(state("IDLE"),1));}
    @Test public void tasksReadyPrintingCompletePreparationMissingHaveDistinctRanks()throws Exception {JSONArray a=new JSONArray().put(file("missing").put("missing",1)).put(file("source").put("is_printable",0)).put(file("done").put("required_qty",3).put("printed_qty",3)).put(file("printing").put("status","printing")).put(file("ready"));assertEquals("ready,printing,done,source,missing",names(FarmSort.files(a,"ready",false),"filename"));assertEquals("missing,source,done,printing,ready",names(FarmSort.files(a,"ready",true),"filename"));}
    @Test public void overproductionIsCompleteAndStillPrintable()throws Exception {JSONObject f=file("a").put("required_qty",1).put("printed_qty",4).put("compatible_pids",new JSONArray().put("p"));assertEquals(FarmSort.FileState.COMPLETE,FarmSort.fileState(f));assertTrue(PrintRequest.compatible(f,"p"));}
    @Test public void zeroOrAbsentPlanDoesNotInventCompletion()throws Exception {assertEquals(FarmSort.FileState.READY,FarmSort.fileState(file("a")));assertEquals(FarmSort.FileState.READY,FarmSort.fileState(file("b").put("required_qty",0).put("printed_qty",5)));}
    @Test public void incompleteTaskPlanRemainsReady()throws Exception {assertEquals(FarmSort.FileState.READY,FarmSort.fileState(file("a").put("required_qty",10).put("printed_qty",9)));}
    @Test public void missingFileIsMissingEvenAfterCompletedPlan()throws Exception {assertEquals(FarmSort.FileState.MISSING,FarmSort.fileState(file("a").put("required_qty",1).put("printed_qty",1).put("missing",true)));}
    @Test public void missingPrintableFlagNeverAdvertisesReadiness() {assertEquals(FarmSort.FileState.PREPARING,FarmSort.fileState(new JSONObject()));}
    @Test public void noSlicedFileIsPreparationRegardlessOfPlan()throws Exception {assertEquals(FarmSort.FileState.PREPARING,FarmSort.fileState(file("a").put("is_printable",false).put("printed_qty",3).put("required_qty",1)));}
    @Test public void activeFileNotCompleteEvenWithCompletedPlan()throws Exception {assertEquals(FarmSort.FileState.PRINTING,FarmSort.fileState(file("a").put("status","printing").put("printed_qty",3).put("required_qty",1)));}
    @Test public void allProjectPartsMustMeetTheirOwnPlan()throws Exception {JSONObject f=file("a").put("children",new JSONArray().put(part("a",10,5)).put(part("b",0,5)));assertEquals(FarmSort.FileState.READY,FarmSort.fileState(f));f.getJSONArray("children").getJSONObject(1).put("printed_qty",5);assertEquals(FarmSort.FileState.COMPLETE,FarmSort.fileState(f));}
    @Test public void activeSharedPartUsesActualCoreInProgressState()throws Exception {JSONObject f=file("a").put("children",new JSONArray().put(part("p",0,2).put("status","in_progress")));assertEquals(FarmSort.FileState.PRINTING,FarmSort.fileState(f));assertNotEquals(FarmSort.fileCaption(f),FarmSort.fileCaption(file("b").put("status","printing")));}
    @Test public void noLinkedPartsDoesNotInventCompleteProject()throws Exception {assertEquals(FarmSort.FileState.READY,FarmSort.fileState(file("a").put("children",new JSONArray())));}
    @Test public void sharedPartPlansAreVisibleUnderEveryLinkedFile()throws Exception {JSONObject first=file("first").put("children",new JSONArray().put(part("p",2,2).put("extra_files",new JSONArray().put(new JSONObject().put("file_id","second").put("on_plate_qty",3).put("file_part_id","link")))));JSONObject second=file("second").put("children",new JSONArray());JSONArray source=new JSONArray().put(first).put(second),copy=FarmSort.projectFiles(source);assertEquals(FarmSort.FileState.COMPLETE,FarmSort.fileState(copy.getJSONObject(1)));assertEquals(3,copy.getJSONObject(1).getJSONArray("children").getJSONObject(0).getInt("on_plate_qty"));assertEquals(0,second.getJSONArray("children").length());}
    @Test public void repeatedExtraReferencesDoNotDoubleCountParts()throws Exception {JSONObject ref=new JSONObject().put("file_id","b");JSONArray nodes=new JSONArray().put(file("a").put("children",new JSONArray().put(part("p",1,2).put("extra_files",new JSONArray().put(ref).put(ref))))).put(file("b").put("children",new JSONArray()));assertEquals(1,FarmSort.projectFiles(nodes).getJSONObject(1).getJSONArray("children").length());}
    @Test public void unknownExtraReferenceDoesNotCreateFile()throws Exception {JSONArray nodes=new JSONArray().put(file("a").put("children",new JSONArray().put(part("p",1,2).put("extra_files",new JSONArray().put(new JSONObject().put("file_id","deleted"))))));assertEquals(1,FarmSort.projectFiles(nodes).length());}
    @Test public void sortingCannotMutateOriginalServerOrderOrMetadata()throws Exception {JSONArray source=new JSONArray().put(file("z")).put(file("a"));String before=source.toString();FarmSort.files(source,"name",false);FarmSort.projectFiles(source);assertEquals(before,source.toString());}
    @Test public void presentationCopiesDoNotChangePrintRequest()throws Exception {JSONObject f=file("f").put("children",new JSONArray().put(part("p",1,2)));String expected=new PrintRequest("project",f.getString("file_id"),f.getString("filename"),"printer",null,null).body().toString();JSONObject copy=FarmSort.projectFiles(new JSONArray().put(f)).getJSONObject(0);assertEquals(expected,new PrintRequest("project",copy.getString("file_id"),copy.getString("filename"),"printer",null,null).body().toString());}
    @Test public void oldOrCorruptPreferenceFallsBackToSupportedOption(){assertEquals("status",FarmSort.mode("ready",true));assertEquals("name",FarmSort.mode("model",false));assertEquals("name",FarmSort.mode("garbage",false));}
    @Test public void emptyListsAreValid(){assertTrue(FarmSort.files(null,"name",false).isEmpty());assertEquals(0,FarmSort.projectFiles(null).length());assertTrue(FarmSort.printers(new JSONArray(),new JSONObject(),0,"status",false).isEmpty());}
    @Test public void largeNumericSuffixDoesNotOverflow()throws Exception {JSONArray source=new JSONArray().put(file("p1000000000000000000000000000000")).put(file("p999999999999999999999999999999"));assertEquals("p999999999999999999999999999999,p1000000000000000000000000000000",names(FarmSort.files(source,"name",false),"filename"));}
    @Test public void russianAndEnglishNamesAreSupported()throws Exception {I18n.setLanguage("ru");try{JSONArray source=new JSONArray().put(file("Ящик2")).put(file("Болт10")).put(file("Болт2"));assertEquals("Болт2,Болт10,Ящик2",names(FarmSort.files(source,"name",false),"filename"));I18n.setLanguage("en");assertEquals("Ready to print",FarmSort.fileCaption(file("part")));}finally{I18n.setLanguage("ru");}}
    @Test public void comparatorHasConsistentOrderingAcrossMixedNames()throws Exception {Random random=new Random(20);String[] words={"A1","A01","A2","A10","Я2","Я10","B-2","B.1","a","","2","10","C1a","C1b"};JSONArray source=new JSONArray();for(int i=0;i<words.length;i++)source.put(file(words[i]));String sorted=names(FarmSort.files(source,"name",false),"filename");for(int run=0;run<50;run++){List<String> shuffled=new ArrayList<>(Arrays.asList(words));Collections.shuffle(shuffled,random);JSONArray mix=new JSONArray();for(String word:shuffled)mix.put(file(word));assertEquals(sorted,names(FarmSort.files(mix,"name",false),"filename"));}}
}
